import os, re
hits=[]
for root,dirs,files in os.walk('.'):
    if '.git' in root or '__pycache__' in root: continue
    for f in files:
        if not f.endswith(('.py','.rst','.txt','.md','.ics','.cfg','.ini')): continue
        p=os.path.join(root,f)
        try:
            lines=open(p,encoding='utf-8',errors='replace').read().splitlines()
        except Exception: continue
        for i,l in enumerate(lines):
            # a line that is (or begins with) FREQ= as *output* (not doctest input)
            if re.match(r'^\s*FREQ=', l) and not re.match(r'^\s*(>>>|\.\.\.)', l):
                hits.append((p,i+1,l.strip(),'bare FREQ line'))
            # DTSTART line followed by a FREQ line without RRULE:
            if re.match(r'^\s*DTSTART:', l):
                for j in range(i+1, min(i+4, len(lines))):
                    nxt=lines[j]
                    if re.match(r'^\s*FREQ=', nxt):
                        hits.append((p,j+1,nxt.strip(),'DTSTART followed by bare FREQ'))
for h in hits: print(h)
print('total hits:', len(hits))
EOF
